lock.sql_a:
BEGIN ISOLATION LEVEL READ COMMITTED, READ WRITE;
SELECT student_id,campus_id FROM university.students WHERE student_id IN (1,2) ORDER BY student_id;
UPDATE university.students SET campus_id=campus_id+1 WHERE student_id=1;
COMMIT;

